// Tope diario 15 (LOTE) + DETECTOR DE SECTOR + CRITICIDADES horneadas (v2)
const TOPE = 15;
const hoy = $now.toFormat('yyyy-LL-dd');
const rows = $('Leer todos los leads').all().map(i=>i.json).filter(r=>r && r.ID_Lead);
const enviadosHoy = rows.filter(r => String(r.Ultimo_Contacto).slice(0,10)===hoy && r.Estado==='contactado').length;
const remaining = TOPE - enviadosHoy;
if (remaining <= 0) return [];
const cand = rows.filter(r => ['pendiente','no_contactado'].includes(String(r.Estado)) && String(r.Correo||'').includes('@'));
if (!cand.length) return [];
cand.sort((a,b)=> (Number(b.Pre_Score)||0) - (Number(a.Pre_Score)||0));
const sel = cand.slice(0, remaining);

// ===== DETECTOR DE SECTOR-BRIEF + SUBSECTOR (auto por empresa/sector/micro-ICP) =====
function deacc(s){return (s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
const FOOD=["carne","carnic","lacteo","leche","queso","bebida","agua","refresc","jugo","cerveza","aliment","confit","dulce","choc","panific","harina","botana","embotellad","conserva"];
const CHEM=["quimic","reactivo","petroquim","plastic","polimero","resina","recubrimiento","adhesivo","pintura"];
const PHARMA=["farmac","laboratorio","medicament","dispositivo","biomedic","medico","biotec"];
function sectorBrief(empresa,sector,micro){
  const e=deacc(empresa), s=deacc(sector);
  if(micro==='ICP-1') return 'MEM_AIS_MX_ENER';
  if(micro==='ICP-2') return 'MEM_AIS_MX_FIN';
  if(micro==='ICP-3'){
    if(PHARMA.some(k=>e.includes(k))) return 'MEM_AIS_MX_FARMDM';
    if(CHEM.some(k=>e.includes(k))) return 'MEM_AIS_MX_QUIM';
    if(FOOD.some(k=>e.includes(k))) return 'MEM_AIS_MX_ALIBEB';
    return 'MEM-AIS-MX-MFG';
  }
  if(s.includes('logist')||s.includes('transporte')) return 'MEM_AIS_MX_LOGTRANS';
  if(s.includes('automotriz')||s.includes('movilidad')) return 'MEM_AIS_MX_AUTO';
  if(s.includes('turismo')||s.includes('hoteler')) return 'MEM_AIS_MX_TURHOSP';
  if(s.includes('construccion')) return 'MEM_AIS_MX_CONST';
  if(s.includes('mineria')) return 'MEM_AIS_MX_MIN';
  if(s.includes('energia')||s.includes('hidrocarbur')) return 'MEM_AIS_MX_ENER';
  return '';
}
